"""Mobile Google import -> real preview -> durable trash -> explicit restore, using only an owned HTTP provider."""
import asyncio,json,os
from pathlib import Path
from playwright.async_api import async_playwright,expect
ROOT=Path(__file__).resolve().parents[4]
async def main():
 server=await asyncio.create_subprocess_exec('node','apps/server/test/support/google-connect-browser-server.ts',cwd=ROOT,env={**os.environ,'YOURWIKI_TEST_GOOGLE_AUTHORIZED':'1'},stdin=asyncio.subprocess.PIPE,stdout=asyncio.subprocess.PIPE,stderr=asyncio.subprocess.PIPE)
 async def command(value):
  server.stdin.write((value+'\n').encode());await server.stdin.drain();return json.loads(await asyncio.wait_for(server.stdout.readline(),45))
 try:
  assert b'Owned Google' in await asyncio.wait_for(server.stdout.readline(),20)
  async with async_playwright() as p:
   browser=await p.chromium.launch(executable_path=os.environ['PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH'],headless=True,args=['--no-sandbox']);context=await browser.new_context(locale='ru-RU',viewport={'width':393,'height':852});page=await context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));origin='http://localhost:39099'
   login=await context.request.post(origin+'/api/auth/login',headers={'origin':origin},data={'username':'qa','password':'yourwiki-qa'});assert login.status==200
   await page.goto(origin+'/settings');await page.get_by_text('Файлы Google',exact=True).click();panel=page.get_by_role('region',name='Файлы Google — Owned Google',exact=True);imports=page.get_by_role('region',name='Импорт в YourWiki',exact=True)
   await panel.get_by_role('button',name='Найти файлы',exact=True).click();await expect(panel.get_by_text('Поиск ожидает выполнения…',exact=True)).to_be_visible();assert await command('discover')=={'result':'discovered'};await expect(panel.get_by_text('Страница результатов готова.',exact=True)).to_be_visible();await panel.locator('.google-discovery-list li').filter(has_text='Заметки.xlsx').get_by_role('button',name='Импортировать',exact=True).click();await imports.get_by_label('Название в YourWiki',exact=True).fill('Google lifecycle');await imports.get_by_label('Группа доступа',exact=True).select_option(label='Owned group');await imports.get_by_role('button',name='Начать импорт',exact=True).click();await expect(imports.get_by_text('В очереди',exact=True)).to_be_visible();assert await command('import')=={'result':'imported'};assert await command('preview')=={'result':'published'};await imports.get_by_role('button',name='Проверить импорт',exact=True).click();await expect(imports.get_by_role('link',name='Открыть',exact=True)).to_be_visible();await imports.get_by_role('link',name='Открыть',exact=True).click();await expect(page.get_by_role('heading',name='Google lifecycle',exact=True)).to_be_visible();await expect(page.locator('iframe')).to_be_visible()
   await page.get_by_role('button',name='В корзину',exact=True).click();dialog=page.get_by_role('dialog');await expect(dialog).to_be_visible();assert await page.evaluate('document.documentElement.scrollWidth<=innerWidth');target=ROOT/'output/playwright/google-trash-mobile-confirm.png';target.parent.mkdir(parents=True,exist_ok=True);await page.screenshot(path=str(target),full_page=True)
   await dialog.get_by_role('button',name='Переместить в корзину',exact=True).click();await expect(page).to_have_url(origin+'/settings');trash=page.get_by_role('region',name='Корзина Google',exact=True);await expect(trash.get_by_text('Google lifecycle',exact=True)).to_be_visible();assert await command('trash-stats')=={'writes':0};assert await command('trash')=={'result':'confirmed'};await trash.get_by_role('button',name='Проверить корзину',exact=True).click();await expect(trash.get_by_role('button',name='Восстановить',exact=True)).to_be_visible();await trash.get_by_role('button',name='Восстановить',exact=True).click();assert await command('trash')=={'result':'confirmed'};await trash.get_by_role('button',name='Проверить корзину',exact=True).click();await expect(trash.get_by_role('link',name='Открыть',exact=True)).to_be_visible();assert await command('trash-stats')=={'writes':2};assert await page.evaluate('document.documentElement.scrollWidth<=innerWidth');await page.screenshot(path=str(ROOT/'output/playwright/google-trash-mobile-restored.png'),full_page=True);await trash.get_by_role('link',name='Открыть',exact=True).click();await expect(page.get_by_role('heading',name='Google lifecycle',exact=True)).to_be_visible();await expect(page.locator('iframe')).to_be_visible();assert not errors,errors;print(json.dumps({'googleTrash':'passed','previewBeforeOpen':True,'sameOriginalRestore':True,'providerWrites':2,'mobileOverflow':False,'pageErrors':errors}));await browser.close()
 finally:
  if server.returncode is None:server.terminate()
  try:await asyncio.wait_for(server.wait(),15)
  except asyncio.TimeoutError:server.kill();await server.wait()
asyncio.run(main())
